Record pfH (mem : word -> option byte) (sp : word) (w can : Z) : Prop := PFH {
  Psp16  : bv_unsigned sp mod 16 = 0;
  PspLo  : 0x131420 <= bv_unsigned sp;
  PspHi  : bv_unsigned sp <= 0x7fffffffffff;
  Pstk   : stk_ok RSEGS mem sp PF_FR;
  Pimg   : forall i, 0x10000 <= i < 0xf4000 -> mem (Z_to_bv 64 i) = None;   (* [comment removed for export] *)
  Pgot   : rdn RSEGS mem (Z_to_bv 64 0xfbc78) 8 = Some (word_to_le_bytes 8 (Z_to_bv 64 0x12ec38)); (* [comment removed for export] *)
  Pflags : rdn RSEGS mem (Z_to_bv 64 0xfcfd8) 4 = Some (word_to_le_bytes 4 (Z_to_bv 64 5));
  Pwend  : rdn RSEGS mem (Z_to_bv 64 0xfcff8) 8 = Some (word_to_le_bytes 8 (Z_to_bv 64 0x12f7e8));
  Pwpos  : rdn RSEGS mem (Z_to_bv 64 0xfd000) 8 = Some (word_to_le_bytes 8 (Z_to_bv 64 w));
  Pw     : 0x12f3e8 <= w <= 0x12f7e6;
  Pbsz   : rdn RSEGS mem (Z_to_bv 64 0xfd038) 8 = Some (word_to_le_bytes 8 (Z_to_bv 64 1024));
  Plock  : rdn RSEGS mem (Z_to_bv 64 0xfd064) 4 = Some (word_to_le_bytes 4 (Z_to_bv 64 4294967295));
  Plbf   : rdn RSEGS mem (Z_to_bv 64 0xfd068) 4 = Some (word_to_le_bytes 4 (Z_to_bv 64 4294967295));
  Pcan   : rdn RSEGS mem (Z_to_bv 64 0x12ec38) 8 = Some (word_to_le_bytes 8 (Z_to_bv 64 can));
  Pcan64 : 0 <= can < 2 ^ 64 }.

